/** E2E check result of one message as a qualifier value; QLF_DEBOUNCE: no verdict (no new data). */
uint8_t qualifierOf(E2E_PCheckStatusType const status)
{
    switch (status)
    {
        case E2E_P_OK: return QLF_OK;
        case E2E_P_REPEATED:
        case E2E_P_WRONGSEQUENCE: return QLF_ERROR_ALIVE;
        case E2E_P_NONEWDATA: return QLF_DEBOUNCE;
        default: return QLF_ERROR_CRC; // E2E_P_ERROR (checksum or data id), E2E_P_NOTAVAILABLE
    }
}

// E2E P01 of PC_Command: CRC PcCrc (bit offset 32), counter PcCounter (40)
E2E_P01ConfigType const PC_Command_E2E_CONFIG = {/* CounterOffset */ 40U, /* CRCOffset */ 32U, /* DataID */ 0x0210U, /* DataIDNibbleOffset */ 0U, /* DataIDMode */ E2E_P01_DATAID_BOTH, /* DataLength */ 64U, /* MaxDeltaCounterInit */ 1U, /* MaxNoNewOrRepeatedData */ 14U, /* SyncCounterInit */ 1U};
E2E_P01CheckStateType PC_Command_E2E_CHECK;

uint8_t checkPC_Command(uint8_t const* const data)
{
    E2E_P01CheckStateType& state = PC_Command_E2E_CHECK;
    // Called for received frames only: the counter tolerance of the legacy profiles grows with every call,
    // so calling it in every task cycle would widen it until it accepts any counter. "No new data" is the
    // job of the timeout supervision below.
    E2E_ReturnType const rc
        = E2E_P01Check(&PC_Command_E2E_CONFIG, &state, data, CANDB_PC_COMMAND_LENGTH);
    return qualifierOf(E2E_P01MapStatusToSM(rc, state.Status, true));
}

