/** Bus error for every received message of the bus: transceiver not open (muted, closed) or bus off. */
bool canBusError()
{
    // Before the RTE is attached (CAN comes up in an earlier lifecycle level) nothing is known about the
    // bus: the messages stay QLF_DEBOUNCE, as after a reset.
    if (canTransceiver == nullptr)
    {
        return false;
    }
    // Not open: muted because the transceiver part is not ready, or closed (CanPhyGate).
    if (canTransceiver->getState() != ::can::ICanTransceiver::State::OPEN)
    {
        return true;
    }
    // Bus off only. PASSIVE (error passive) is not a bus error: the bus still works, and a node alone
    // on its bus reaches that state regularly - reporting it would hide timeout, checksum and counter
    // states again, exactly the effect the COM-03 board test showed (COM-12).
    return canTransceiver->getCANTransceiverState()
           == ::can::ICANTransceiverStateListener::CANTransceiverState::BUS_OFF;
}

void readCan()
{
    if (!canStarted)
    {
        startCan();
    }
    if (canTransceiver == nullptr)
    {
        ::can::ICanTransceiver* const transceiver = ::systems::getCanSystem().getCanTransceiver(::busid::CAN0);
        if (transceiver != nullptr)
        {
            transceiver->addCANFrameListener(rxListener);
            canTransceiver = transceiver;
        }
    }
    bool const busError = canBusError();
    {
        uint8_t data[8];
        bool const fresh = takeRx(0U, data);
        uint8_t const verdict = fresh ? checkPC_Command(data) : QLF_DEBOUNCE;
        if (fresh && (verdict == QLF_OK))
        {
            CanDb_PC_Command_t msg;
            CanDb_PC_Command_Unpack(&msg, data);
            applyPC_Command(msg);
        }
        superviseRx(0U, fresh, verdict, busError, &startValuePC_Command);
        Rte_Buf_CanQlf_PC_Command = CAN_RX_STATUS[0].qlf; // can.qlf.PC_Command
    }
}

void writeCan()
{
    // canTick keeps running while the transmission is off: the messages come back in their own phase, and
    // the E2E counter continues where it stopped, so the receiver sees no gap in the sequence.
    if ((canTransceiver != nullptr) && (canTransceiver->getState() == ::can::ICanTransceiver::State::OPEN)
        && applicationTxEnabled)
    {
        if ((canTick % 10U) == 0U)
        {
            CanDb_EVB_Status_t msg;
            CanDb_EVB_Status_Init(&msg);
            msg.Led1 = CanDb_EVB_Status_Led1_FromInt((Rte_Buf_DemoSwc_Led1_Led1 != 0U) ? 1 : 0);
            msg.Led2 = CanDb_EVB_Status_Led2_FromInt((Rte_Buf_DemoSwc_Led2_Led2 != 0U) ? 1 : 0);
            msg.MotorNtcFiltered_mV = CanDb_EVB_Status_MotorNtcFiltered_mV_FromInt(static_cast<int64_t>(Rte_Buf_DemoSwc_MotorNtcFiltered_mV_MotorNtcFiltered_mV));
            uint8_t data[8] = {0U};
            CanDb_EVB_Status_Pack(&msg, data);
            // E2E after packing: counter and CRC overwrite their signal positions
            if (E2E_P11Protect(
                    &EVB_Status_E2E_CONFIG,
                    &EVB_Status_E2E_PROTECT,
                    data,
                    CANDB_EVB_STATUS_LENGTH)
                != E2E_E_OK)
            {
                ++CAN_TX_STATUS[0].protectErrors;
            }
            ::can::CANFrame const frame(CANDB_EVB_STATUS_ID, data, CANDB_EVB_STATUS_LENGTH);
            if (canTransceiver->write(frame) == ::can::ICanTransceiver::ErrorCode::CAN_ERR_OK)
            {
                ++CAN_TX_STATUS[0].sent;
            }
            else
            {
                ++CAN_TX_STATUS[0].failed;
            }
        }
        if ((canTick % 10U) == 0U)
        {
            CanDb_EVB_Analog_t msg;
            CanDb_EVB_Analog_Init(&msg);
            msg.MotorNtcCoarse_mV = CanDb_EVB_Analog_MotorNtcCoarse_mV_FromInt(static_cast<int64_t>(Rte_Buf_DemoSwc_MotorNtcFiltered_mV_MotorNtcFiltered_mV));
            msg.MotorNtcFine_mV = CanDb_EVB_Analog_MotorNtcFine_mV_FromInt(static_cast<int64_t>(Rte_Buf_DemoSwc_MotorNtcFiltered_mV_MotorNtcFiltered_mV));
            uint8_t data[8] = {0U};
            CanDb_EVB_Analog_Pack(&msg, data);
            ::can::CANFrame const frame(CANDB_EVB_ANALOG_ID, data, CANDB_EVB_ANALOG_LENGTH);
            if (canTransceiver->write(frame) == ::can::ICanTransceiver::ErrorCode::CAN_ERR_OK)
            {
                ++CAN_TX_STATUS[1].sent;
            }
            else
            {
                ++CAN_TX_STATUS[1].failed;
            }
        }
    }
    ++canTick;
}
