void setApplicationTxEnabled(bool const enabled) { applicationTxEnabled = enabled; }

bool isCanAttached() { return canTransceiver != nullptr; }

char const* canBusStateName()
{
    if (canTransceiver == nullptr)
    {
        return "not attached";
    }
    switch (canTransceiver->getState())
    {
        case ::can::ICanTransceiver::State::CLOSED: return "closed";
        case ::can::ICanTransceiver::State::INITIALIZED: return "initialized";
        case ::can::ICanTransceiver::State::WAKING: return "waking";
        case ::can::ICanTransceiver::State::MUTED: return "muted (phy not ready)";
        default: break; // OPEN: the state of the bus itself decides
    }
    switch (canTransceiver->getCANTransceiverState())
    {
        case ::can::ICANTransceiverStateListener::CANTransceiverState::BUS_OFF: return "bus off";
        case ::can::ICANTransceiverStateListener::CANTransceiverState::PASSIVE: return "error passive";
        default: return "error active";
    }
}

// ---- task swc (TASK_SWC, 10 ms) ----
namespace
{
void readInputs_swc()
{
    readCan();
    {
        bool value = false;
        if (::bios::DigitalInput::get(::bios::DigitalInput::BUTTON1, value) == ::bsp::BSP_OK)
        {
            Rte_Buf_DemoSwc_Button1_Button1 = value ? 1U : 0U;
        }
    }
    {
        uint32_t value = 0U;
        if (::bios::AnalogInputScale::get(::bios::AnalogInput::Ai_MOTOR_NTC, value) == ::bsp::BSP_OK)
        {
            Rte_Buf_DemoSwc_MotorNtc_mV_MotorNtc_mV = static_cast<uint32>(value);
        }
    }
}

void writeOutputs_swc()
{
    writeCan();
    (void)::bios::Output::set(::bios::Output::LED1, (Rte_Buf_DemoSwc_Led1_Led1 != 0U) ? 1U : 0U);
    (void)::bios::Output::set(::bios::Output::LED2, (Rte_Buf_DemoSwc_Led2_Led2 != 0U) ? 1U : 0U);
}
} // namespace

void readInputs(size_t const task)
{
    switch (task)
    {
        case 0U: readInputs_swc(); break;
        default: break;
    }
}

void writeOutputs(size_t const task)
{
    switch (task)
    {
        case 0U: writeOutputs_swc(); break;
        default: break;
    }
}

void init()
{
    if (!canStarted)
    {
        startCan(); // CAN start values of the received signals and the E2E states
    }
}

