uint8_t demSample(size_t const dtc)
{
    ::async::LockType const lock;
    switch (dtc)
    {
        case 0U: // MotorNtcOpenCircuit: DemoSwc.MotorNtcFiltered_mV.MotorNtcFiltered_mV (limit)
        {
            return ((Rte_Buf_DemoSwc_MotorNtcFiltered_mV_MotorNtcFiltered_mV > 4900U)) ? 3U : 2U;
        }
        case 1U: // PcCommandTimeout: DemoSwc.PcCommandQlf.PcCommandQlf (qualifier)
        {
            return (Rte_Buf_CanQlf_PC_Command == 1U) ? 2U : (((Rte_Buf_CanQlf_PC_Command == 0U) || (Rte_Buf_CanQlf_PC_Command == 64U)) ? 255U : 3U);
        }
        default: return 255U; // reported by the BSW (dem::IFaultMemory::report)
    }
}

